/**
 * Problem metadata for the JINA multi-scenario robust interactive method.
 *
 * All fields are optional with generic fallbacks resolved at request time (see
 * `desdeo.api.routers.district_heating_robust_data`) — a problem needs none of these set to
 * work with the method; they exist to let a problem author override the generic defaults
 * (display labels/units, dedup tolerance, default thresholds) the way the district heating
 * problem's own values were hand-picked before this table existed.
 */
export interface JinaMultiScenarioMetaData {
	id?: number | null;
	metadata_id?: number | null;
	metadata_type?: string;
	/** {objective_symbol: threshold}, pre-fills the DM-editable domain-criterion inputs. */
	default_domain_thresholds?: JinaMultiScenarioMetaDataDefaultDomainThresholds;
	/** {objective_symbol: floor}, pre-fills the antifragility-floor inputs. */
	default_af_absolute_floors?: JinaMultiScenarioMetaDataDefaultAfAbsoluteFloors;
	/** Absolute dedup tolerance for strategic-design signatures, in each strategic variable's own units. */
	design_tolerance?: number;
	/** Generic-ASF shift factor for the per-objective emphasis scalarizer variants. */
	emphasis_factor?: number;
	/** Scenario name treated as the undisrupted baseline; falls back to a name-based heuristic, then the first scenario. */
	baseline_scenario?: string | null;
	/** 'module.path:function' resolving to a compound-disruption scenario builder; absent means the compound-disruption stress test is unavailable for this problem. */
	compound_scenario_hook?: string | null;
	/** 'module.path:function' resolving to a builder for the baseline + single-disruption reference scenarios compound_scenario_hook's combos pair from; absent means super-additivity can't be computed (the compound-disruption stress test still works without it, just without that extra heatmap). */
	compound_reference_hook?: string | null;
	/** Identifier for an optional precomputed pool to blend into regret/antifragility normalization, resolved by the analysis code; absent means session-discovered designs only. */
	regret_pool_source?: string | null;
	/** {symbol: display label} override for strategic (first-stage) variables. */
	strategic_var_labels?: JinaMultiScenarioMetaDataStrategicVarLabels;
	/** {symbol: short component name}, e.g. for compact table columns. */
	strategic_var_components?: JinaMultiScenarioMetaDataStrategicVarComponents;
	/** {symbol: unit string}, e.g. 'MW'. */
	strategic_var_units?: JinaMultiScenarioMetaDataStrategicVarUnits;
}

